// HasMessages applies the HasEdge predicate on the "messages" edge.
func HasMessages() predicate.WhatsAppConversation {
	return predicate.WhatsAppConversation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, MessagesTable, MessagesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMessagesWith applies the HasEdge predicate on the "messages" edge with a given conditions (other predicates).
func HasMessagesWith(preds ...predicate.WhatsAppMessage) predicate.WhatsAppConversation {
	return predicate.WhatsAppConversation(func(s *sql.Selector) {
		step := newMessagesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WhatsAppConversation) predicate.WhatsAppConversation {
	return predicate.WhatsAppConversation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WhatsAppConversation) predicate.WhatsAppConversation {
	return predicate.WhatsAppConversation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WhatsAppConversation) predicate.WhatsAppConversation {
	return predicate.WhatsAppConversation(sql.NotPredicates(p))
}
